var numFriendRequests = function(ages) {
    const count = new Array(121).fill(0);
    const prefix = new Array(121).fill(0);
    for (const a of ages) count[a]++;
    for (let i = 1; i <= 120; i++) prefix[i] = prefix[i - 1] + count[i];
    let ans = 0;
    for (let a = 15; a <= 120; a++) {
        if (count[a] === 0) continue;
        const low = Math.floor(a / 2) + 7;
        const validY = prefix[a] - prefix[low];
        ans += count[a] * (validY - 1);
    }
    return ans;
};
